alter table public.room_reports add constraint room_reports_no_self_target_check check (target_user_id is null or target_user_id <> reporter_id), add constraint room_reports_reason_length_check check (char_length(btrim(reason)) between 3 and 100), add constraint room_reports_details_length_check check (details is null or char_length(details) <= 1000); create unique index room_reports_one_target_report_per_room_idx on public.room_reports(room_id,reporter_id,target_user_id) where target_user_id is not null; create unique index room_reports_one_room_report_per_room_idx on public.room_reports(room_id,reporter_id) where target_user_id is null;
